package com.hbm.client.reactor.rbmk.display;
import com.hbm.machine.reactor.rbmk.display.RbmkDisplayEntity;
import com.hbm.multiblock.DummyableBlock;
import com.mojang.blaze3d.vertex.*;
import com.mojang.math.Axis;
import net.minecraft.client.renderer.*;
import net.minecraft.client.renderer.blockentity.*;
import net.minecraft.util.Mth;
/** Original RenderRBMKDisplay: exact source matrices,49heat/color cells and three-quad fuel/control dots. */
public final class RbmkDisplayRenderer implements BlockEntityRenderer<RbmkDisplayEntity>{
    public RbmkDisplayRenderer(BlockEntityRendererProvider.Context context){}
    @Override public void render(RbmkDisplayEntity display,float partial,PoseStack poses,MultiBufferSource buffers,int light,int overlay){poses.pushPose();poses.translate(.5,0,.5);float angle=switch(display.getBlockState().getValue(DummyableBlock.LEGACY_META)){case 2->90;case 4->180;case 3->270;default->0;};poses.mulPose(Axis.YP.rotationDegrees(angle));poses.translate(0,.5,0);poses.scale(1,8F/7F,8F/7F);poses.translate(0,-.5,0);var out=buffers.getBuffer(Colors.PANELS);for(int i=0;i<49;i++){var column=display.columns[i];if(column==null)continue;var data=column.data();float x=.28125F,y=-(i/7)*.125F+.875F,z=-(i%7)*.125F+.375F,r,g,b;if(data.contains("color")&&data.getByte("color")>=0){int color=switch(data.getByte("color")){case 0->0xff0000;case 1->0xffff00;case 2->0x008000;case 3->0x0000ff;case 4->0x8000ff;default->0xffffff;};r=(color>>16&255)/255F;g=(color>>8&255)/255F;b=(color&255)/255F;}else{double heat=data.getDouble("heat")/data.getDouble("maxHeat"),color=.65+i%2*.05;r=(float)(color+(1-color)*heat);g=b=(float)color;}if(data.getByte("indicator")>0){r=g=1;b=0;}float width=.0625F*.75F;quad(out,poses,new float[][]{{x,y+width,z-width},{x,y+width,z+width},{x,y-width,z+width},{x,y-width,z-width}},r,g,b);switch(column.type()){case FUEL,FUEL_SIM->dot(out,poses,x+.01F,y,z,0,.25F+(float)(data.getDouble("enrichment")*.75),0);case CONTROL->{float level=(float)data.getDouble("level");dot(out,poses,x+.01F,y,z,level,level,0);}case CONTROL_AUTO->{float level=(float)data.getDouble("level");dot(out,poses,x+.01F,y,z,level,0,level);}default->{}}}poses.popPose();}
    private static void quad(VertexConsumer out,PoseStack poses,float[][] vertices,float r,float g,float b){for(var vertex:vertices)out.addVertex(poses.last().pose(),vertex[0],vertex[1],vertex[2]).setColor(Mth.clamp(r,0,1),Mth.clamp(g,0,1),Mth.clamp(b,0,1),1);}
    private static void dot(VertexConsumer out,PoseStack poses,float x,float y,float z,float r,float g,float b){float width=.03125F,edge=.022097F;quad(out,poses,new float[][]{{x,y+width,z},{x,y+edge,z+edge},{x,y,z+width},{x,y-edge,z+edge}},r,g,b);quad(out,poses,new float[][]{{x,y+edge,z-edge},{x,y+width,z},{x,y-edge,z-edge},{x,y,z-width}},r,g,b);quad(out,poses,new float[][]{{x,y+width,z},{x,y-edge,z+edge},{x,y-width,z},{x,y-edge,z-edge}},r,g,b);}
    private static final class Colors extends RenderType{private Colors(){super("unused",DefaultVertexFormat.POSITION_COLOR,VertexFormat.Mode.QUADS,256,false,false,()->{},()->{});}static final RenderType PANELS=create("hbm_rbmk_display_panels",DefaultVertexFormat.POSITION_COLOR,VertexFormat.Mode.QUADS,4096,false,false,CompositeState.builder().setShaderState(POSITION_COLOR_SHADER).setCullState(CULL).setWriteMaskState(COLOR_DEPTH_WRITE).createCompositeState(false));}
}
